 "content": "def transform(grid):
    """Expand each isolated clue cell into its encoded horizontal color motif."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Contiguous nonzero runs of length >= 2 are the motif definitions.
    motifs = []
    source_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            run = row[start:c]
            if len(run) >= 2:
                motifs.append(run)
                source_cells.update((r, j) for j in range(start, c))

    # Every remaining colored singleton is a seed: align its matching motif
    # color at the seed's column, then stamp the complete motif horizontally.
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0 or (r, c) in source_cells:
                continue
            choices = [(m.index(color), m) for m in motifs if color in m]
            if not choices:
                continue
            # In the demonstrated tasks each seed color identifies one motif.
            idx, motif = choices[0]
            start = c - idx
            for k, value in enumerate(motif):
                x = start + k
                if 0 <= x < w:
                    g[r][x] = value
    return g
